import 'dart:convert';
import 'dart:io';

/// Generates `lib/src/tokens.g.dart` from `docs/design/tokens.json`.
///
/// Run from packages/pirc_ui: `dart run tool/generate_tokens.dart`.
/// `test/tokens_test.dart` fails when the generated file is stale.
void main() {
  const output = 'lib/src/tokens.g.dart';
  File(
    output,
  ).writeAsStringSync(generateTokens(File(tokensPath).readAsStringSync()));
  final format = Process.runSync(Platform.resolvedExecutable, [
    'format',
    output,
  ]);
  if (format.exitCode != 0) throw StateError('${format.stderr}');
}

const tokensPath = '../../docs/design/tokens.json';

String generateTokens(String source) {
  final tokens = jsonDecode(source) as Map<String, dynamic>;
  final out = StringBuffer()
    ..writeln('// Generated by tool/generate_tokens.dart from')
    ..writeln('// docs/design/tokens.json. Do not edit.')
    ..writeln('// ignore_for_file: constant_identifier_names')
    ..writeln()
    ..writeln("import 'package:flutter/animation.dart';")
    ..writeln("import 'package:flutter/painting.dart';")
    ..writeln()
    ..writeln("import 'token_types.dart';")
    ..writeln();

  final color = tokens['color'] as Map<String, dynamic>;
  for (final (name, group) in [
    ('pircLightColors', 'light'),
    ('pircDarkColors', 'dark'),
    ('pircTerminalColors', 'terminal'),
  ]) {
    out.writeln('const $name = <String, Color>{');
    for (final MapEntry(:key, :value) in _values(color[group])) {
      out.writeln("  '$key': Color(${_hex(_color(value as String))}),");
    }
    out.writeln('};');
    out.writeln();
  }

  out.writeln('/// Type scale: font size, line height and weight per role.');
  out.writeln('abstract final class PircType {');
  for (final MapEntry(:key, :value) in _values(tokens['typography'])) {
    if (value is! Map) continue;
    final spec = value.cast<String, dynamic>();
    final args = [
      'size: ${_num(spec['size'])}',
      if (spec['lineHeight'] != null) 'lineHeight: ${_num(spec['lineHeight'])}',
      if (spec['weight'] != null) 'weight: ${spec['weight']}',
      if (spec['letterSpacing'] != null)
        'letterSpacing: ${_num(spec['letterSpacing'])}',
      if (spec['color'] != null) "color: '${spec['color']}'",
    ];
    out.writeln(
      '  static const ${_identifier(key)} = PircTypeSpec(${args.join(', ')});',
    );
  }
  out.writeln('}');
  out.writeln();

  for (final (className, group) in [
    ('PircRadius', 'radius'),
    ('PircSpacing', 'spacing'),
    ('PircSize', 'size'),
  ]) {
    out.writeln('abstract final class $className {');
    for (final MapEntry(:key, :value) in _values(tokens[group])) {
      out.writeln(
        '  static const double ${_identifier(key)} = ${_num(value)};',
      );
    }
    out.writeln('}');
    out.writeln();
  }

  out.writeln(
    '/// Shadows; an empty list means the surface relies on its fill.',
  );
  out.writeln('abstract final class PircElevation {');
  for (final MapEntry(:key, :value) in _values(tokens['elevation'])) {
    final modes = (value as Map).cast<String, String>();
    for (final mode in ['light', 'dark']) {
      final name = _identifier('$key.$mode');
      out.writeln('  static const $name = <BoxShadow>[');
      for (final shadow in _shadows(modes[mode]!)) {
        out.writeln('    $shadow,');
      }
      out.writeln('  ];');
    }
  }
  out.writeln('}');
  out.writeln();

  final layout = tokens['layout'] as Map<String, dynamic>;
  out.writeln('/// Smallest window width of each layout.');
  out.writeln('abstract final class PircBreakpoints {');
  for (final name in ['portrait', 'landscape', 'desktop']) {
    final minWidth = (layout[name] as Map)['minWidth'];
    out.writeln('  static const double $name = ${_num(minWidth)};');
  }
  out.writeln('}');
  out.writeln();

  final motion = tokens['motion'] as Map<String, dynamic>;
  final ease = RegExp(
    r'cubic-bezier\(([^)]*)\)',
  ).firstMatch(motion['ease'] as String)![1]!.split(',').map(_num).join(', ');
  out
    ..writeln('abstract final class PircMotion {')
    ..writeln('  static const ease = Cubic($ease);')
    ..writeln(
      '  static const fast = Duration(milliseconds: ${motion['fast']});',
    )
    ..writeln(
      '  static const sheet = Duration(milliseconds: ${motion['sheet']});',
    )
    ..writeln('}');
  return out.toString();
}

Iterable<MapEntry<String, dynamic>> _values(Object? group) =>
    (group as Map<String, dynamic>).entries.where(
      (entry) => !entry.key.startsWith(r'$'),
    );

/// `#RRGGBB` or `rgba(r,g,b,a)` → ARGB.
int _color(String value) {
  final hex = RegExp(r'^#([0-9a-fA-F]{6})$').firstMatch(value.trim());
  if (hex != null) return 0xff000000 | int.parse(hex[1]!, radix: 16);
  final rgba = RegExp(
    r'^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+)\s*)?\)$',
  ).firstMatch(value.trim());
  if (rgba == null) throw FormatException('Unsupported color', value);
  final alpha = ((double.parse(rgba[4] ?? '1')) * 255).round();
  return alpha << 24 |
      int.parse(rgba[1]!) << 16 |
      int.parse(rgba[2]!) << 8 |
      int.parse(rgba[3]!);
}

/// `0 1 2 rgba(...), 0 6 20 rgba(...)` → BoxShadow constructors.
List<String> _shadows(String value) {
  if (value.trim().startsWith('none')) return const [];
  final shadow = RegExp(
    r'(-?[\d.]+)\s+(-?[\d.]+)\s+([\d.]+)\s+(rgba\([^)]*\))',
  );
  return [
    for (final match in shadow.allMatches(value))
      'BoxShadow(offset: Offset(${_num(match[1])}, ${_num(match[2])}), '
          'blurRadius: ${_num(match[3])}, '
          'color: Color(${_hex(_color(match[4]!.replaceAll(RegExp(r',\.'), ',0.')))}))',
  ];
}

String _hex(int value) =>
    '0x${value.toRadixString(16).padLeft(8, '0').toUpperCase()}';

String _num(Object? value) {
  final number = value is num ? value : num.parse('$value'.trim());
  return number == number.roundToDouble() && number is! double
      ? '$number'
      : number.toDouble().toString();
}

/// `touchTarget.min` → `touchTargetMin`; `gutter.phone` → `gutterPhone`.
String _identifier(String key) {
  final parts = key.split(RegExp(r'[.\-]'));
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}
